"""Upstream/downstream lineage tracing over a declared node/edge graph.

The public entry point is :func:`trace_lineage`. Edges point from
``source`` to ``target``: upstream traversal follows edges backwards,
downstream traversal follows them forwards.

Graph structure problems raise :class:`InvalidLineageInputError`, bad query
arguments raise :class:`InvalidLineageQueryError` and a target that is not
declared in ``nodes`` raises :class:`UnknownLineageTargetError`; all three
subclass :class:`ValueError`.
"""

from __future__ import annotations

from collections import deque
from typing import Any, Dict, List, Optional, Set, Tuple

__all__ = [
    "trace_lineage",
    "InvalidLineageInputError",
    "InvalidLineageQueryError",
    "UnknownLineageTargetError",
]

VALID_DIRECTIONS = ("upstream", "downstream", "both")
_EDGE_KEYS = frozenset({"source", "target"})


class InvalidLineageInputError(ValueError):
    """The lineage graph (``nodes``/``edges``) is missing or malformed."""


class InvalidLineageQueryError(ValueError):
    """The query arguments (``target``/``direction``/``max_depth``) are bad."""


class UnknownLineageTargetError(ValueError):
    """The queried ``target`` is not declared among ``nodes``."""


def _validate_graph(nodes: Any, edges: Any) -> Set[str]:
    if not isinstance(nodes, list):
        raise InvalidLineageInputError("nodes must be a list of node ids")
    if not nodes:
        raise InvalidLineageInputError("nodes must not be empty")

    declared: Set[str] = set()
    for index, node in enumerate(nodes):
        if not isinstance(node, str):
            raise InvalidLineageInputError(
                f"nodes[{index}] must be a string"
            )
        if not node:
            raise InvalidLineageInputError(
                f"nodes[{index}] must be a non-empty string"
            )
        if node in declared:
            raise InvalidLineageInputError(f"duplicate node id: {node!r}")
        declared.add(node)

    if not isinstance(edges, list):
        raise InvalidLineageInputError("edges must be a list")

    seen_edges: Set[Tuple[str, str]] = set()
    for index, edge in enumerate(edges):
        if not isinstance(edge, dict):
            raise InvalidLineageInputError(f"edges[{index}] must be an object")

        keys = set(edge)
        if keys != _EDGE_KEYS:
            missing = sorted(_EDGE_KEYS - keys)
            if missing:
                raise InvalidLineageInputError(
                    f"edges[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - _EDGE_KEYS)
            raise InvalidLineageInputError(
                f"edges[{index}] has unsupported keys: {unknown}"
            )

        source = edge["source"]
        target = edge["target"]
        if not isinstance(source, str) or source not in declared:
            raise InvalidLineageInputError(
                f"edges[{index}].source is not a declared node: {source!r}"
            )
        if not isinstance(target, str) or target not in declared:
            raise InvalidLineageInputError(
                f"edges[{index}].target is not a declared node: {target!r}"
            )

        pair = (source, target)
        if pair in seen_edges:
            raise InvalidLineageInputError(
                f"duplicate edge: {source!r} -> {target!r}"
            )
        seen_edges.add(pair)

    return declared


def _validate_query(
    target: Any, direction: Any, max_depth: Any
) -> None:
    if not isinstance(target, str):
        raise InvalidLineageQueryError("target must be a node id string")
    if direction not in VALID_DIRECTIONS:
        raise InvalidLineageQueryError(
            f"direction must be one of {list(VALID_DIRECTIONS)}, "
            f"got {direction!r}"
        )
    if max_depth is not None:
        # bool is a subclass of int, but JSON true/false are not depths.
        if isinstance(max_depth, bool) or not isinstance(max_depth, int):
            raise InvalidLineageQueryError(
                "max_depth must be null or an integer >= 0"
            )
        if max_depth < 0:
            raise InvalidLineageQueryError(
                f"max_depth must be >= 0, got {max_depth}"
            )


def _build_adjacency(
    edges: List[Dict[str, str]]
) -> Tuple[Dict[str, List[str]], Dict[str, List[str]]]:
    outgoing: Dict[str, List[str]] = {}
    incoming: Dict[str, List[str]] = {}
    for edge in edges:
        source = edge["source"]
        target = edge["target"]
        outgoing.setdefault(source, []).append(target)
        incoming.setdefault(target, []).append(source)
    return outgoing, incoming


def _walk(
    start: str,
    neighbors: Dict[str, List[str]],
    max_depth: Optional[int],
) -> Dict[str, int]:
    """BFS from ``start``; first visit wins, so depths are shortest."""
    depths = {start: 0}
    if max_depth == 0:
        return depths

    queue = deque([(start, 0)])
    while queue:
        node, depth = queue.popleft()
        if max_depth is not None and depth >= max_depth:
            continue
        next_depth = depth + 1
        for nxt in neighbors.get(node, ()):
            if nxt not in depths:
                depths[nxt] = next_depth
                queue.append((nxt, next_depth))
    return depths


def _side(
    depths: Optional[Dict[str, int]],
    edges: List[Dict[str, str]],
) -> Dict[str, Any]:
    if depths is None:
        return {"nodes": [], "edges": []}

    nodes = [
        {"id": node_id, "depth": depth}
        for node_id, depth in sorted(depths.items(), key=lambda item: (item[1], item[0]))
    ]
    side_edges = [
        edge
        for edge in edges
        if edge["source"] in depths and edge["target"] in depths
    ]
    side_edges.sort(key=lambda edge: (edge["source"], edge["target"]))
    return {"nodes": nodes, "edges": side_edges}


def trace_lineage(
    nodes: Any,
    edges: Any,
    target: Any,
    direction: Any = "both",
    max_depth: Any = None,
) -> Dict[str, Any]:
    """Trace upstream/downstream lineage of ``target``.

    :param nodes: non-empty list of distinct non-empty node id strings.
    :param edges: list of ``{"source": ..., "target": ...}`` objects whose
        endpoints are declared in ``nodes``; duplicate edges are rejected.
    :param target: node id to trace from; depth 0 in every returned side.
    :param direction: ``"upstream"``, ``"downstream"`` or ``"both"``
        (default ``"both"``).
    :param max_depth: ``None`` for unlimited (default) or an integer ``>= 0``;
        ``0`` returns only ``target``. Booleans are not integers here.
    :returns: ``{"target", "direction", "max_depth",
        "upstream": {"nodes", "edges"}, "downstream": {"nodes", "edges"}}``.
        Each populated side lists nodes as ``{"id", "depth"}`` sorted by
        ``(depth, id)`` and includes every original edge whose endpoints are
        in the side, sorted by ``(source, target)``. The side not queried is
        returned empty.
    :raises ValueError: :class:`InvalidLineageInputError`,
        :class:`InvalidLineageQueryError` or
        :class:`UnknownLineageTargetError`.
    """
    declared = _validate_graph(nodes, edges)
    _validate_query(target, direction, max_depth)

    if target not in declared:
        raise UnknownLineageTargetError(
            f"target is not declared in nodes: {target!r}"
        )

    outgoing, incoming = _build_adjacency(edges)

    upstream_depths: Optional[Dict[str, int]] = None
    downstream_depths: Optional[Dict[str, int]] = None
    if direction in ("upstream", "both"):
        upstream_depths = _walk(target, incoming, max_depth)
    if direction in ("downstream", "both"):
        downstream_depths = _walk(target, outgoing, max_depth)

    return {
        "target": target,
        "direction": direction,
        "max_depth": max_depth,
        "upstream": _side(upstream_depths, edges),
        "downstream": _side(downstream_depths, edges),
    }

"""Command line interface: ``dq validate`` and ``dq lineage``.

Both subcommands read a UTF-8 JSON object from standard input and write a
UTF-8 JSON result to standard output.

``dq validate`` reads ``{"records": [...], "rules": [...]}``.
``dq lineage`` reads ``{"nodes": [...], "edges": [...], "target": ...,
"direction": ..., "max_depth": ...}`` where ``direction`` and ``max_depth``
are optional.

Error JSON has the shape ``{"error": {"code": ..., "message": ...}}`` and
the process exits with status 2:

* ``INVALID_JSON``            - stdin is not parseable UTF-8 JSON
* ``INVALID_INPUT``           - validate payload/records structure is malformed
* ``INVALID_RULE``            - a validate rule is malformed or conflicting
* ``INVALID_LINEAGE_INPUT``   - lineage nodes/edges are missing or malformed
* ``INVALID_LINEAGE_QUERY``   - lineage target/direction/max_depth is invalid
* ``UNKNOWN_LINEAGE_TARGET``  - lineage target is not declared in nodes
"""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any, List, Optional

from .lineage import (
    InvalidLineageInputError,
    InvalidLineageQueryError,
    UnknownLineageTargetError,
    trace_lineage,
)
from .validator import (
    DataQualityError,
    InvalidInputError,
    InvalidRuleError,
    validate,
)

EXIT_OK = 0
EXIT_ERROR = 2

# Sentinel distinguishing "error already emitted" from a parsed payload.
_PARSE_FAILED = object()


def _emit_error(code: str, message: str) -> int:
    payload = {"error": {"code": code, "message": message}}
    json.dump(payload, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_ERROR


def _read_json_payload() -> Any:
    """Read stdin as a UTF-8 JSON value.

    Returns the parsed value, or ``_PARSE_FAILED`` after emitting an
    ``INVALID_JSON`` error.
    """
    raw = sys.stdin.buffer.read()

    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        _emit_error("INVALID_JSON", f"input is not valid UTF-8: {exc}")
        return _PARSE_FAILED

    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        _emit_error("INVALID_JSON", f"input is not valid JSON: {exc.msg}")
        return _PARSE_FAILED


def _run_validate() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_INPUT", "input payload must be a JSON object"
        )
    if "records" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'records'")
    if "rules" not in payload:
        return _emit_error("INVALID_INPUT", "payload is missing 'rules'")

    try:
        result = validate(payload["records"], payload["rules"])
    except InvalidRuleError as exc:
        return _emit_error("INVALID_RULE", str(exc))
    except InvalidInputError as exc:
        return _emit_error("INVALID_INPUT", str(exc))
    except DataQualityError as exc:
        return _emit_error(exc.code, str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def _run_lineage() -> int:
    payload = _read_json_payload()
    if payload is _PARSE_FAILED:
        return EXIT_ERROR

    if not isinstance(payload, dict):
        return _emit_error(
            "INVALID_LINEAGE_INPUT", "input payload must be a JSON object"
        )

    try:
        result = trace_lineage(
            payload.get("nodes"),
            payload.get("edges"),
            payload.get("target"),
            payload.get("direction", "both"),
            payload.get("max_depth", None),
        )
    except InvalidLineageInputError as exc:
        return _emit_error("INVALID_LINEAGE_INPUT", str(exc))
    except InvalidLineageQueryError as exc:
        return _emit_error("INVALID_LINEAGE_QUERY", str(exc))
    except UnknownLineageTargetError as exc:
        return _emit_error("UNKNOWN_LINEAGE_TARGET", str(exc))

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dq",
        description="Data quality rule validation and lineage tracing.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    validate_parser = subparsers.add_parser(
        "validate",
        help="validate records from a UTF-8 JSON object on standard input",
    )
    validate_parser.set_defaults(handler=_run_validate)

    lineage_parser = subparsers.add_parser(
        "lineage",
        help="trace upstream/downstream lineage from a UTF-8 JSON object "
        "on standard input",
    )
    lineage_parser.set_defaults(handler=_run_lineage)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.handler()


if __name__ == "__main__":
    sys.exit(main())

"""Core validation logic for the data_quality package.

The public entry point is :func:`validate`. It validates a list of JSON
object records against a list of rules and returns a result dictionary with
``passed`` / ``summary`` / ``violations``.

Structural problems raise :class:`InvalidInputError` and rule configuration
problems raise :class:`InvalidRuleError`; both subclass :class:`ValueError`.
"""

from __future__ import annotations

import re
from typing import Any, Dict, List

__all__ = [
    "validate",
    "DataQualityError",
    "InvalidInputError",
    "InvalidRuleError",
]

SUPPORTED_TYPES = ("required", "unique", "range", "regex", "allowed_values")

MESSAGES = {
    "required": "is required but is missing or null",
    "unique": "is a duplicate value",
    "range": "is out of the allowed range",
    "regex": "does not match the required pattern",
    "allowed_values": "is not in the list of allowed values",
}


class DataQualityError(ValueError):
    """Base class for validation errors. Carries an CLI error ``code``."""

    code = "INVALID_INPUT"


class InvalidInputError(DataQualityError):
    """The records argument (or the enclosing payload) is malformed."""

    code = "INVALID_INPUT"


class InvalidRuleError(DataQualityError):
    """A rule is malformed, unsupported or has conflicting options."""

    code = "INVALID_RULE"


def _is_number(value: Any) -> bool:
    # bool is a subclass of int, but JSON true/false are not numbers.
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _json_equal(left: Any, right: Any) -> bool:
    """JSON value equality.

    Unlike Python ``==`` this never considers booleans equal to numbers
    (JSON ``true`` is not ``1``) and compares containers structurally.
    """
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(
            _json_equal(a, b) for a, b in zip(left, right)
        )
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(
            _json_equal(left[k], right[k]) for k in left
        )
    return left == right


def _rule_error(message: str) -> InvalidRuleError:
    return InvalidRuleError(message)


def _validate_and_compile_rules(rules: Any) -> List[Dict[str, Any]]:
    if not isinstance(rules, list):
        raise _rule_error("rules must be a list")

    compiled: List[Dict[str, Any]] = []
    seen_ids: set = set()

    for index, rule in enumerate(rules):
        if not isinstance(rule, dict):
            raise _rule_error(f"rules[{index}] must be an object")

        rule_id = rule.get("id")
        if not isinstance(rule_id, str) or not rule_id:
            raise _rule_error(f"rules[{index}] must have a non-empty string id")
        if rule_id in seen_ids:
            raise _rule_error(f"duplicate rule id: {rule_id!r}")
        seen_ids.add(rule_id)

        rule_type = rule.get("type")
        if not isinstance(rule_type, str):
            raise _rule_error(f"rule {rule_id!r} must have a string type")
        if rule_type not in SUPPORTED_TYPES:
            raise _rule_error(
                f"rule {rule_id!r} has unsupported type: {rule_type!r}"
            )

        options = rule.get("options")
        if not isinstance(options, dict):
            raise _rule_error(f"rule {rule_id!r} must have an options object")

        field = options.get("field")
        if not isinstance(field, str):
            raise _rule_error(
                f"rule {rule_id!r}: options.field must be a string"
            )

        allowed_keys = {"field"}
        compiled_rule: Dict[str, Any] = {
            "id": rule_id,
            "type": rule_type,
            "field": field,
        }

        if rule_type == "range":
            allowed_keys |= {"min", "max"}
            minimum = options.get("min")
            maximum = options.get("max")
            if not _is_number(minimum):
                raise _rule_error(
                    f"rule {rule_id!r}: options.min must be a number"
                )
            if not _is_number(maximum):
                raise _rule_error(
                    f"rule {rule_id!r}: options.max must be a number"
                )
            if minimum > maximum:
                raise _rule_error(
                    f"rule {rule_id!r}: options.min ({minimum}) must not be "
                    f"greater than options.max ({maximum})"
                )
            compiled_rule["min"] = minimum
            compiled_rule["max"] = maximum

        elif rule_type == "regex":
            allowed_keys.add("pattern")
            pattern = options.get("pattern")
            if not isinstance(pattern, str):
                raise _rule_error(
                    f"rule {rule_id!r}: options.pattern must be a string"
                )
            try:
                compiled_rule["pattern"] = re.compile(pattern)
            except re.error as exc:
                raise _rule_error(
                    f"rule {rule_id!r}: options.pattern is not a valid "
                    f"regular expression: {exc}"
                ) from exc

        elif rule_type == "allowed_values":
            allowed_keys.add("values")
            values = options.get("values")
            if not isinstance(values, list):
                raise _rule_error(
                    f"rule {rule_id!r}: options.values must be a list"
                )
            compiled_rule["values"] = values

        unknown = set(options) - allowed_keys
        if unknown:
            raise _rule_error(
                f"rule {rule_id!r}: unsupported options for type "
                f"{rule_type!r}: {sorted(unknown)}"
            )

        compiled.append(compiled_rule)

    return compiled


def _violation(rule: Dict[str, Any], index: int, record: Dict[str, Any], value: Any):
    record_id = record["id"] if "id" in record else None
    return {
        "rule_id": rule["id"],
        "record_index": index,
        "record_id": record_id,
        "field": rule["field"],
        "value": value,
        "message": MESSAGES[rule["type"]],
    }


def _check_rule(
    rule: Dict[str, Any],
    records: List[Dict[str, Any]],
    violations: List[Dict[str, Any]],
) -> None:
    rule_type = rule["type"]
    field = rule["field"]

    if rule_type == "unique":
        seen: List[Any] = []

    for index, record in enumerate(records):
        present = field in record
        value = record.get(field)

        if rule_type == "required":
            if not present or value is None:
                violations.append(_violation(rule, index, record, value))

        elif rule_type == "unique":
            # Null values are excluded from uniqueness checks.
            if value is not None:
                if any(_json_equal(value, earlier) for earlier in seen):
                    violations.append(_violation(rule, index, record, value))
                else:
                    seen.append(value)

        elif rule_type == "range":
            if not _is_number(value) or not (
                rule["min"] <= value <= rule["max"]
            ):
                violations.append(_violation(rule, index, record, value))

        elif rule_type == "regex":
            if not isinstance(value, str) or rule["pattern"].fullmatch(value) is None:
                violations.append(_violation(rule, index, record, value))

        elif rule_type == "allowed_values":
            checked = value if present else None
            if not any(_json_equal(checked, allowed) for allowed in rule["values"]):
                violations.append(_violation(rule, index, record, checked))


def validate(records: Any, rules: Any) -> Dict[str, Any]:
    """Validate ``records`` against ``rules``.

    Rules are fully validated before any record is examined. Rules are then
    evaluated in their given order; within a rule, records are checked in
    order.

    :param records: list of JSON objects (plain ``dict`` instances).
    :param rules: list of rule objects with ``id``, ``type`` and ``options``.
    :returns: ``{"passed": bool, "summary": {...}, "violations": [...]}``.
    :raises ValueError: on malformed input or rule configuration.
    """
    compiled_rules = _validate_and_compile_rules(rules)

    if not isinstance(records, list):
        raise InvalidInputError("records must be a list")
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise InvalidInputError(f"records[{index}] must be a JSON object")

    violations: List[Dict[str, Any]] = []
    for rule in compiled_rules:
        _check_rule(rule, records, violations)

    return {
        "passed": not violations,
        "summary": {
            "record_count": len(records),
            "violation_count": len(violations),
            "checked_rule_count": len(compiled_rules),
        },
        "violations": violations,
    }

